Local Ltac transport_chunks segs m a bs ::= transport_chunks_fast segs m a bs.
Local Ltac footprint_after_store segs m a bs ::= footprint_after_store_fast segs m a bs.
Local Ltac mem_after_store ::= mem_after_store_fast.

(* [comment removed for export] *)
Definition nc_val (minval maxval : Z) (j : Z) : Z := minval + Z.quot (j * (maxval - minval)) 9.
Definition nc_words (minval maxval : Z) (n : nat) : list word := map (fun j => Z_to_bv 64 (nc_val minval maxval (Z.of_nat j))) (seq 0 n).
Lemma nc_words_S : forall mn mx n, nc_words mn mx (S n) = nc_words mn mx n ++ [Z_to_bv 64 (nc_val mn mx (Z.of_nat n))].
Proof.
