Lemma nc_arith : forall mn mx i, 0 <= mn <= 255 -> 0 <= mx <= 255 -> 0 <= i <= 9 ->
  Z_to_bv 64 (bv_unsigned (v_divw (Z_to_bv 64 (bv_swrap 32 (bv_unsigned (sx32 (Z_to_bv 64 mx)) - bv_unsigned (sx32 (Z_to_bv 64 mn)))
                                           mod 18446744073709551616 * i)) (Z_to_bv 64 9))
              + bv_unsigned (sx32 (Z_to_bv 64 mn)))
