Lemma nc_loop : forall (k : nat) (i : Z)
    (ra sp gp tp t0 t1 t2 s0 s1 a2 a4 a5 a6 a7 s6 s8 s9 s10 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32) (m0 m : mem)
    (nc pmin pmax minval maxval : Z),
  Z.of_nat k = 10 - i -> 0 <= i -> (1 <= k)%nat ->
  0 < nc -> nc mod 16 = 0 -> nc + 40 <= 2^47 -> (nc + 40 <= 0x7fff7000 \/ 0x10007fff8000 <= nc) ->
  0 <= minval <= 255 -> 0 <= maxval <= 255 ->
  (forall m', munch [(nc, nc + 40)] m0 m' -> wmono asegs m0 m' ->
              rw_cells asegs m' pmin [C4 (Z_to_bv 64 minval)] /\ rw_cells asegs m' pmax [C4 (Z_to_bv 64 maxval)]) ->
  munch [(nc, nc + 40)] m0 m -> wmono asegs m0 m ->
  u32arr asegs m nc (nc_words minval maxval (Z.to_nat i)) -> wr_at asegs m nc 40 -> acc asegs m nc 40 -> mem_inv asegs m ->
  evt asegs (bc_nc_exit nc ra sp gp tp s0 s1 (Z_to_bv 64 pmin) (Z_to_bv 64 pmax) (Z_to_bv 64 9) s6 (Z_to_bv 64 2147450880) s8 s9 s10
                        (Z_to_bv 64 nc) F fc m0)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 (nc + 4 * i)) (Z_to_bv 64 i) a2 (Z_to_bv 64 (nc + 4 * i)) a4 a5 a6 a7
